#include "domain/exterior_residents.hpp"
#include <iostream>
using namespace stalthos;using namespace stalthos::fauna;
int main(){try{std::vector<HabitatSite> sites{{{0,0,24},true,true,{1}},{{12,0,24},true,true,{0}}};Population old(42,1001,sites,8,{1});auto habitat=exteriorHabitat(sites,[](double,double){return 0.;},[](double,double){return false;});auto expanded=withExteriorResidents(old,habitat,{1});auto before=old.snapshot(),after=expanded.snapshot();if(after.actors.size()!=12)throw std::runtime_error("resident count");for(std::size_t i=0;i<8;++i){auto a=before.actors[i],b=after.actors[i];if(a.id!=b.id||a.position.x!=b.position.x||a.position.z!=b.position.z||a.target!=b.target||a.thirst!=b.thirst||a.activity!=b.activity)throw std::runtime_error("old actor changed");}std::set<Identity> ids;for(auto a:after.actors)if(!ids.insert(a.id).second||a.id==1)throw std::runtime_error("identitycollision");for(int i=0;i<20;++i)expanded.advance({1,1},false);auto later=expanded.snapshot();Population restored(42,1001,habitat.sites,12,{1});restored.restore(later,{1});for(std::size_t i=8;i<12;++i)if(later.actors[i].id!=after.actors[i].id||later.actors[i].distanceTravelledMeters<=0||later.actors[i].calendarAge<=after.actors[i].calendarAge)throw std::runtime_error("resident not retained/live");bool rejected=false;try{exteriorHabitat(sites,[](double,double){return 0.;},[](double x,double){return x>50;});}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("wetedge accepted");std::cout<<"EXTERIOR_RESIDENTS_OK original8 identity exclusion live4 dryedges continuation\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
